class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        na, nb, nc = a, b, c
        ans = 0
        for _ in range(n):
            ans = min(na, nb, nc)
            if na == ans: na += a
            if nb == ans: nb += b
            if nc == ans: nc += c
        return ans

