import math

class Solution:
    def nthUglyNumber(self, n: int, a: int, b: int, c: int) -> int:
        def lcm(x, y):
            return x // math.gcd(x, y) * y
        lab, lac, lbc = lcm(a, b), lcm(a, c), lcm(b, c)
        labc = lcm(lab, c)
        def count(x):
            return x // a + x // b + x // c - x // lab - x // lac - x // lbc + x // labc
        lo, hi = 1, 2 * 10 ** 9
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= n:
                hi = mid
            else:
                lo = mid + 1
        return lo

