var nthUglyNumber = function(n, a, b, c) {
    const gcd = (x, y) => y === 0 ? x : gcd(y, x % y);
    const lcm = (x, y) => x / gcd(x, y) * y;
    const lab = lcm(a, b), lac = lcm(a, c), lbc = lcm(b, c);
    const labc = lcm(lab, c);
    const count = x =>
        Math.floor(x / a) + Math.floor(x / b) + Math.floor(x / c)
        - Math.floor(x / lab) - Math.floor(x / lac) - Math.floor(x / lbc)
        + Math.floor(x / labc);
    let lo = 1, hi = 2e9;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (count(mid) >= n) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};
